{
  "families": [
    {
      "budget_share": 40,
      "family": "pipelined",
      "ranges": [
        {"choices": null, "high": 20, "low": 12, "param": "data_width"},
        {"choices": null, "high": 24, "low": 10, "param": "n_iter"},
        {"choices": null, "high": 4, "low": -2, "param": "angle_guard"},
        {"choices": null, "high": 4, "low": 0, "param": "frac_guard"},
        {"choices": ["trunc", "round"], "high": null, "low": null, "param": "rounding"}
      ],
      "why": "One registered stage per micro-rotation gives the highest Fmax (throughput = Fmax, easily >=50 MSPS) and is the reference for the power/accuracy trade-off; W>=14 with N>=14 is the plausible region for the 2^-12 error bound, with guards and rounding as accuracy knobs."
    },
    {
      "budget_share": 60,
      "family": "pipelined_m",
      "ranges": [
        {"choices": null, "high": 20, "low": 12, "param": "data_width"},
        {"choices": null, "high": 24, "low": 10, "param": "n_iter"},
        {"choices": null, "high": 4, "low": -2, "param": "angle_guard"},
        {"choices": null, "high": 4, "low": 0, "param": "frac_guard"},
        {"choices": ["trunc", "round"], "high": null, "low": null, "param": "rounding"},
        {"choices": null, "high": 8, "low": 2, "param": "m"}
      ],
      "why": "Registering every m stages cuts the flip-flop count (and hence power_index) at the cost of a longer combinational path; since power is the objective and throughput only needs Fmax>=50 MHz, this family is the most likely to reach the low-power end of the front. m=2..8 spans the FF-vs-Fmax trade-off."
    }
  ],
  "rationale": "Both allowed families emit one result per cycle, so throughput_msps equals Fmax and the 50 MSPS constraint is a mild Fmax floor. The binding constraint is max_abs_err <= 2^-12, which needs roughly data_width >= 14 with n_iter >= 14 plus guard bits; the power objective rewards fewer pipeline registers, so pipelined_m (larger m) should dominate the low-power end while pipelined anchors the high-Fmax end. Round 1 therefore searches W=12..20, N=10..24, angle_guard=-2..4, frac_guard=0..4, both roundings, and m=2..8, with a larger share on pipelined_m to map the power-optimal region."
}
